// ============================================================================
//  Normalisation + validation des payloads entrants
//  Accepte 3 formats : BotpressService, NotificationService, et lot (recipients)
// ============================================================================
const cfg = $json.cfg || {};
const out = [];

function onlyDigits(v) {
  return String(v == null ? '' : v).replace(/[^0-9]/g, '');
}

// Retourne le numero au format Meta (chiffres, sans '+') ou null si invalide
function normalizePhone(raw) {
  let d = onlyDigits(raw);
  if (!d) return null;
  if (d.startsWith('00')) d = d.slice(2);
  // Numero senegalais saisi en local : 77 123 45 67 -> 221771234567
  if (d.length === 9 && d.startsWith('7')) d = String(cfg.defaultCountryCode || '221') + d;
  // Doublon d'indicatif eventuel : 221221...
  if (d.startsWith('221221')) d = d.slice(3);
  if (d.length < 10 || d.length > 15) return null;
  return d;
}

// Aplatit les differents formats de payload vers une liste homogene
function collect(body) {
  const list = [];
  if (!body || typeof body !== 'object') return list;

  if (Array.isArray(body.recipients) && body.recipients.length) {
    for (const r of body.recipients) {
      list.push({
        action: r.action || body.action || 'send_whatsapp',
        to: r.to || r.phone || r.whatsapp,
        message: r.message || body.message,
        document: r.document || body.document || null,
        template: r.template || body.template || null,
        variables: r.variables || body.variables || null,
        inSession: r.inSession === true || body.inSession === true,
        category: r.category || body.category || 'generique',
        reference: r.reference || body.reference || null,
      });
    }
    return list;
  }

  // Format NotificationService : { channel, to, payload: { message, subject, ... } }
  if (body.channel && body.payload) {
    list.push({
      action: body.action || (body.payload.document ? 'send_whatsapp_document' : 'send_whatsapp'),
      to: body.to,
      message: body.payload.message,
      document: body.payload.document || null,
      template: body.template || null,
      variables: body.variables || null,
      inSession: body.inSession === true,
      category: body.payload.category || 'relance',
      reference: body.payload.subject || null,
    });
    return list;
  }

  // Format BotpressService : { action, to, message, document? }
  list.push({
    action: body.action || 'send_whatsapp',
    to: body.to || body.phone,
    message: body.message,
    document: body.document || null,
    template: body.template || null,
    variables: body.variables || null,
    inSession: body.inSession === true,
    category: body.category || 'generique',
    reference: body.reference || null,
  });
  return list;
}

const body = $json.body || $json;
const raw = collect(body);

for (const r of raw) {
  const to = normalizePhone(r.to);
  const hasDoc = !!(r.document && (r.document.url || r.document.base64));

  if (!to) {
    out.push({
      json: {
        cfg,
        valid: false,
        mode: 'invalide',
        to: r.to || null,
        toE164: null,
        error: 'Numero de telephone invalide ou absent : ' + String(r.to),
        category: r.category,
        reference: r.reference,
      },
    });
    continue;
  }

  if (!r.message && !hasDoc) {
    out.push({
      json: {
        cfg,
        valid: false,
        mode: 'invalide',
        to,
        toE164: '+' + to,
        error: 'Message vide et aucun document fourni',
        category: r.category,
        reference: r.reference,
      },
    });
    continue;
  }

  // ---- Choix du mode d'envoi -------------------------------------------
  // inSession = true  -> le parent a ecrit dans les dernieres 24h : texte libre OK
  // sinon             -> WhatsApp impose un template pre-approuve
  const route = (cfg.route || 'meta').toLowerCase();
  const tplName = (r.template && r.template.name) || null;
  const needTemplate = !r.inSession;

  let mode;
  if (route === 'botpress') {
    mode = 'botpress';
  } else if (needTemplate) {
    mode = 'template';
  } else if (hasDoc) {
    mode = 'document';
  } else {
    mode = 'texte';
  }

  // Template par defaut selon la categorie fonctionnelle
  const defaults = {
    facture: cfg.templateFacture,
    recu: cfg.templateRecu,
    relance: cfg.templateRelance,
    generique: cfg.templateGenerique,
  };
  const templateName = tplName || defaults[r.category] || cfg.templateGenerique;
  const templateLang = (r.template && r.template.language) || cfg.templateLanguage || 'fr';
  const variables = Array.isArray(r.variables) ? r.variables : [];

  // Composants du template (entete document + variables de corps)
  const components = [];
  if (hasDoc && r.document.url) {
    components.push({
      type: 'header',
      parameters: [
        {
          type: 'document',
          document: {
            link: r.document.url,
            filename: r.document.filename || 'document.pdf',
          },
        },
      ],
    });
  }
  if (variables.length) {
    components.push({
      type: 'body',
      parameters: variables.map((v) => ({ type: 'text', text: String(v) })),
    });
  }

  if (mode === 'template' && !templateName) {
    out.push({
      json: {
        cfg,
        valid: false,
        mode: 'invalide',
        to,
        toE164: '+' + to,
        error: 'Envoi hors fenetre 24h : aucun template WhatsApp configure pour la categorie ' + r.category,
        category: r.category,
        reference: r.reference,
      },
    });
    continue;
  }

  out.push({
    json: {
      cfg,
      valid: true,
      mode,
      action: r.action,
      to,
      toE164: '+' + to,
      message: r.message || (r.document && r.document.caption) || '',
      category: r.category,
      reference: r.reference,
      inSession: r.inSession === true,
      document: hasDoc
        ? {
            url: r.document.url || null,
            base64: r.document.base64 || null,
            filename: r.document.filename || 'document.pdf',
            mimeType: r.document.mimeType || 'application/pdf',
            caption: r.document.caption || r.message || '',
            mediaId: null,
          }
        : null,
      template: {
        name: templateName,
        language: templateLang,
        components,
        variables,
      },
    },
  });
}

if (!out.length) {
  out.push({
    json: {
      cfg,
      valid: false,
      mode: 'invalide',
      to: null,
      toE164: null,
      error: 'Payload vide ou illisible',
      category: 'generique',
      reference: null,
    },
  });
}

return out;

// Convertit le PDF base64 recu du backend en donnee binaire n8n,
// pour l'upload vers l'endpoint /media de la Cloud API.
const item = $input.first().json;
const doc = item.document || {};
const b64 = String(doc.base64 || '').replace(/^data:[^;]+;base64,/, '');

const buffer = Buffer.from(b64, 'base64');
const binary = await this.helpers.prepareBinaryData(
  buffer,
  doc.filename || 'document.pdf',
  doc.mimeType || 'application/pdf'
);

return [{ json: item, binary: { data: binary } }];

// Recupere le media_id renvoye par Meta et l'injecte dans l'item d'origine.
const src = JSON.parse(JSON.stringify($('Boucle destinataires').first().json));
const res = $input.first().json || {};

if (res.error) {
  src.valid = false;
  src.mode = 'invalide';
  src.error = 'Echec upload media : ' + (res.error.message || JSON.stringify(res.error));
  return [{ json: src }];
}

const mediaId = res.id || null;
if (!mediaId) {
  src.valid = false;
  src.mode = 'invalide';
  src.error = 'Upload media : aucun id retourne par la Cloud API';
  return [{ json: src }];
}

src.document.mediaId = mediaId;
src.document.base64 = null; // on n'a plus besoin du base64 en memoire

// Si on part sur un template, l'entete document utilise desormais le media_id
if (src.mode === 'template') {
  src.template.components = (src.template.components || []).filter((c) => c.type !== 'header');
  src.template.components.unshift({
    type: 'header',
    parameters: [
      { type: 'document', document: { id: mediaId, filename: src.document.filename } },
    ],
  });
}

return [{ json: src }];

const src = $input.first().json;
return [
  {
    json: {
      success: false,
      to: src.toE164 || src.to || null,
      action: src.action || null,
      mode: 'invalide',
      category: src.category || null,
      reference: src.reference || null,
      messageId: null,
      error: src.error || 'Element rejete a la validation',
      documentFilename: null,
      sentAt: new Date().toISOString(),
    },
  },
];

// Normalise la reponse de l'API en un resultat exploitable par le backend
// (pour alimenter la table communication_logs).
const src = $('Boucle destinataires').first().json;
const res = $input.first().json || {};

let success = false;
let messageId = null;
let error = null;

if (res.error) {
  const e = res.error;
  error = (e.message || e.error_user_msg || JSON.stringify(e));
  if (e.code) error = '[' + e.code + '] ' + error;
} else if (Array.isArray(res.messages) && res.messages.length) {
  success = true;
  messageId = res.messages[0].id || null;
} else if (res.success === true || res.status === 'ok' || res.received === true) {
  // Reponse de la route Botpress (integration Webhook)
  success = true;
  messageId = res.messageId || res.conversationId || null;
} else {
  error = 'Reponse inattendue de l API : ' + JSON.stringify(res).slice(0, 400);
}

return [
  {
    json: {
      success,
      to: src.toE164,
      action: src.action,
      mode: src.mode,
      category: src.category,
      reference: src.reference,
      messageId,
      error,
      documentFilename: src.document ? src.document.filename : null,
      sentAt: new Date().toISOString(),
    },
  },
];

// Reponse synchrone renvoyee au backend GeStockPro
const results = $input.all().map((i) => i.json);
const sent = results.filter((r) => r.success).length;

return [
  {
    json: {
      success: sent > 0,
      total: results.length,
      sent,
      failed: results.length - sent,
      results,
      timestamp: new Date().toISOString(),
    },
  },
];
